// === PARSER l'API Google Sheets (rowData) + EXTRAIRE les cases TRUE ===
// Indices BRUTS (colonne A = 0) car la plage commence en A6 :
//   0=Session  1=NOM  2=Prénom  3=Mail(lien mailto)  ...
const MAIL_COLS = [
  { check: 12, date: 10, motif: 11, niveau: '1' },
  { check: 15, date: 13, motif: 14, niveau: '1' },
  { check: 18, date: 16, motif: 17, niveau: '2' },
  { check: 21, date: 19, motif: 20, niveau: '2' },
  { check: 24, date: 22, motif: 23, niveau: '3' },
  { check: 27, date: 25, motif: 26, niveau: '3' },
  { check: 30, date: 28, motif: 29, niveau: '3' },
  { check: 33, date: 31, motif: 32, niveau: '+' },
  { check: 36, date: 34, motif: 35, niveau: '+' },
  { check: 39, date: 37, motif: 38, niveau: '+' },
];

const sources = [
  { node: '📋 API NTC', name: 'NTC' },
  { node: '📋 API AD',  name: 'AD'  },
  { node: '📋 API CC',  name: 'CC'  },
  { node: '📋 API REM', name: 'REM' },
];

const val = (v) => (v && v.formattedValue != null) ? String(v.formattedValue).trim() : '';
const isChecked = (v) => {
  if (!v) return false;
  if (v.effectiveValue && v.effectiveValue.boolValue === true) return true;
  const f = (v.formattedValue || '').toString().toUpperCase();
  return f === 'TRUE' || f === 'VRAI';
};
const getMail = (v) => {
  if (!v) return '';
  let h = v.hyperlink || '';
  return h.replace(/^mailto:/i, '').trim();
};

const results = [];

for (const src of sources) {
  let resp;
  try { resp = $(src.node).first().json; } catch (e) { continue; }
  const data = resp && resp.sheets && resp.sheets[0] && resp.sheets[0].data && resp.sheets[0].data[0];
  const rows = (data && data.rowData) ? data.rowData : [];

  for (let r = 1; r < rows.length; r++) {
    const cells = (rows[r] && rows[r].values) ? rows[r].values : [];
    const nom    = val(cells[1]);
    const prenom = val(cells[2]);
    if (!nom || nom === 'NOM' || nom === '0') continue;

    const mail    = getMail(cells[3]);
    const session = val(cells[0]);
    const feuille = src.name;

    for (let idx = 0; idx < MAIL_COLS.length; idx++) {
      const { check, date, motif, niveau } = MAIL_COLS[idx];
      if (!isChecked(cells[check])) continue;

      const dateVal  = val(cells[date]);
      const motifVal = val(cells[motif]);
      const nomPrenom = `${nom} ${prenom}`.trim();
      const sujet = `Mail niv${niveau} - apprenant ${nomPrenom}`;
      const corps = `Bonjour,\n\nSuivi d'absence - Niveau ${niveau}\n\nApprenant(e) : ${nomPrenom}\nSession      : ${session} (${feuille})\nDate absence : ${dateVal}\nMotif        : ${motifVal}\n\nCordialement`;
      const uniqueKey = `${feuille}_${session}_${nom}_${prenom}_abs${idx}`;

      results.push({ json: { destinataire: mail, sujet, corps, nom, prenom, mail, session, feuille, niveau, dateAbs: dateVal, motif: motifVal, uniqueKey, mailManquant: mail === '' } });
    }
  }
}

return results;

// === SKIP si un brouillon OU un envoyé avec le même SUJET existe déjà ===
// Brouillons : listés directement (resource draft) -> fiables même non indexés.
// Envoyés    : recherche subject: dans in:sent (indexée, donc OK).

function subjOf(j) {
  if (!j) return '';
  if (j.subject) return String(j.subject);
  if (j.Subject) return String(j.Subject);
  if (j.headers && j.headers.subject) return String(j.headers.subject);
  // brouillons (resource draft, simple=false) -> message.payload.headers
  const paths = [
    j.payload && j.payload.headers,
    j.message && j.message.payload && j.message.payload.headers,
  ];
  for (const h of paths) {
    if (Array.isArray(h)) {
      const f = h.find(x => x.name && x.name.toLowerCase() === 'subject');
      if (f) return String(f.value || '');
    }
  }
  return '';
}

const existingSubjects = new Set();
const addFrom = (nodeName) => {
  let items = [];
  try { items = $(nodeName).all(); } catch (e) { items = []; }
  for (const it of items) {
    const s = subjOf(it.json).trim().toLowerCase();
    if (s) existingSubjects.add(s);
  }
};
addFrom('📥 Brouillons existants');
addFrom('📤 Envoyés existants');

let candidates = [];
try { candidates = $('🔍 Parser + extraire TRUE').all(); } catch (e) { candidates = []; }

const seen = new Set();
const out = [];
for (const c of candidates) {
  const subj = (c.json.sujet || '').trim();
  if (!subj) continue;
  const key = subj.toLowerCase();
  if (existingSubjects.has(key)) continue; // déjà créé (brouillon) ou déjà envoyé -> skip
  if (seen.has(key)) continue;             // doublon dans ce run -> skip
  seen.add(key);
  out.push({ json: c.json });
}

return out;
